//! Read-only comparisons generated by Git, never by the turn patch tracker.
use std::path::Path;
use std::path::PathBuf;

use serde::Deserialize;
use serde::Serialize;
use sha2::Digest;
use sha2::Sha256;

use crate::diff_source::DiffSourceRanges;
use crate::diff_source::DiffSourceRequest;

use crate::historical::ReadCancellation;
use crate::historical::disabled_filter_config;
use crate::historical::read_git;
use crate::historical::read_git_command;
use crate::historical::read_git_command_with;
use crate::historical::read_git_lossy;
use crate::historical::relative_git_path;
use crate::historical::resolve_read_revision;
use crate::historical::valid_oid;
use crate::operations::GitCommandControl;

const CAPTURE_LIMIT: usize = 8 * 1024 * 1024;
const MAX_WARNING_BYTES: usize = 2 * 1024;
pub const MAX_PATCH_BYTES: usize = 128 * 1024;
pub const MAX_INSPECTION_ENTRIES: usize = 1000;

#[derive(Clone, Copy, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum DiffComparison {
    Staged,
    Unstaged,
    Revisions,
}

#[derive(Serialize)]
pub struct DiffEndpoint {
    pub kind: &'static str,
    pub revision: Option<String>,
    pub commit_oid: Option<String>,
    pub tree_oid: Option<String>,
}

#[derive(Serialize)]
pub struct DiffFile {
    pub status: String,
    pub old_path: String,
    pub new_path: String,
    pub old_mode: String,
    pub new_mode: String,
    /// Git raw identities: all-zero means unavailable (e.g. live working bytes).
    pub old_oid: String,
    pub new_oid: String,
    pub similarity_percent: Option<u32>,
    pub binary: bool,
    pub additions: Option<u64>,
    pub deletions: Option<u64>,
}

#[derive(Serialize)]
pub struct DiffInspection {
    pub repository_root: PathBuf,
    pub comparison: DiffComparison,
    pub from: DiffEndpoint,
    pub to: DiffEndpoint,
    pub paths: Vec<String>,
    /// Requested paths matching nothing at either endpoint (e.g. wrong case).
    pub unmatched_paths: Vec<String>,
    pub git_args: Vec<String>,
    pub filter_policy: &'static str,
    pub untracked_included: bool,
    pub coherent_snapshot_verified: bool,
    pub total_files: usize,
    pub files: Vec<DiffFile>,
    pub files_truncated: bool,
    pub additions: u64,
    pub deletions: u64,
    pub binary_files: usize,
    pub patch: String,
    pub patch_encoding: &'static str,
    pub total_patch_bytes: usize,
    pub returned_patch_bytes: usize,
    pub patch_truncated: bool,
    pub warnings: String,
    pub diff_sha256: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub source_ranges: Option<DiffSourceRanges>,
}

pub struct DiffRequest {
    pub comparison: DiffComparison,
    pub base: Option<String>,
    pub head: Option<String>,
    pub paths: Vec<String>,
    pub max_patch_bytes: usize,
    pub max_files: usize,
    pub source_ranges: Option<DiffSourceRequest>,
}

pub async fn inspect_diff(cwd: PathBuf, request: DiffRequest) -> Result<DiffInspection, String> {
    let control = GitCommandControl::new();
    let _cancellation = ReadCancellation(control.clone());
    tokio::task::spawn_blocking(move || {
        let root = repository_root(&cwd, &control)?;
        capture_diff(&root, request, &control)
    })
    .await
    .map_err(|error| error.to_string())?
}

pub(crate) fn repository_root(cwd: &Path, control: &GitCommandControl) -> Result<PathBuf, String> {
    let root = read_git(cwd, &["rev-parse", "--show-toplevel"], 32 * 1024, control)?;
    Ok(PathBuf::from(root.trim_end_matches(['\r', '\n'])))
}

fn endpoint(
    root: &Path,
    revision: String,
    control: &GitCommandControl,
) -> Result<DiffEndpoint, String> {
    let commit_oid = resolve_read_revision(root, &revision, control)?;
    let tree_oid = read_git(
        root,
        &["rev-parse", "--verify", &format!("{commit_oid}^{{tree}}")],
        1024,
        control,
    )?
    .trim()
    .to_string();
    if !valid_oid(&tree_oid) {
        return Err("Git did not return one tree identity".into());
    }
    Ok(DiffEndpoint {
        kind: "commit_tree",
        revision: Some(revision),
        commit_oid: Some(commit_oid),
        tree_oid: Some(tree_oid),
    })
}

fn live_endpoint(kind: &'static str) -> DiffEndpoint {
    DiffEndpoint {
        kind,
        revision: None,
        commit_oid: None,
        tree_oid: None,
    }
}

fn capture_diff(
    root: &Path,
    request: DiffRequest,
    control: &GitCommandControl,
) -> Result<DiffInspection, String> {
    let DiffRequest {
        comparison,
        base,
        head,
        paths,
        max_patch_bytes,
        max_files,
        source_ranges,
    } = request;
    if let Some(source) = &source_ranges {
        source.validate()?;
    }
    if max_patch_bytes > MAX_PATCH_BYTES
        || !(1..=MAX_INSPECTION_ENTRIES).contains(&max_files)
        || paths.len() > 64
    {
        return Err("diff limits: patch 0..131072 bytes, files 1..1000, at most 64 paths".into());
    }
    let paths = paths
        .iter()
        .map(|path| relative_git_path(path))
        .collect::<Result<Vec<_>, _>>()?;
    let (from, to) = match comparison {
        DiffComparison::Revisions => (
            endpoint(
                root,
                base.ok_or("revisions comparison requires base")?,
                control,
            )?,
            endpoint(
                root,
                head.ok_or("revisions comparison requires head")?,
                control,
            )?,
        ),
        DiffComparison::Staged | DiffComparison::Unstaged => {
            if base.is_some() || head.is_some() {
                return Err("base/head are only valid for revisions comparisons".into());
            }
            if comparison == DiffComparison::Unstaged {
                (live_endpoint("index"), live_endpoint("working_tree"))
            } else {
                // Do not confuse a broken/missing HEAD object with an unborn branch.
                let head_ref = read_git_command(
                    root,
                    &["rev-parse", "--verify", "--quiet", "HEAD"],
                    1024,
                    control,
                )?;
                if head_ref.status.success() {
                    let oid = String::from_utf8(head_ref.stdout).map_err(|_| "invalid HEAD")?;
                    (
                        endpoint(root, oid.trim().to_string(), control)?,
                        live_endpoint("index"),
                    )
                } else {
                    let branch = read_git(
                        root,
                        &["symbolic-ref", "--quiet", "HEAD"],
                        32 * 1024,
                        control,
                    )?;
                    let exists = read_git_command(
                        root,
                        &["show-ref", "--verify", "--quiet", branch.trim()],
                        1024,
                        control,
                    )?;
                    if exists.status.code() != Some(1) {
                        return Err("HEAD is unavailable, not an unborn branch".into());
                    }
                    let tree = read_git(
                        root,
                        &["hash-object", "-t", "tree", "--stdin"],
                        1024,
                        control,
                    )?
                    .trim()
                    .to_string();
                    (
                        DiffEndpoint {
                            kind: "empty_tree",
                            revision: None,
                            commit_oid: None,
                            tree_oid: Some(tree),
                        },
                        live_endpoint("index"),
                    )
                }
            }
        }
    };
    let mut args = vec!["--literal-pathspecs".to_string()];
    // --no-textconv does not disable clean/process filters. Override every
    // configured driver through Git's own config interface, without running it.
    // Built-in EOL/encoding normalization remains Git's, not a raw-byte claim.
    let filters = if comparison == DiffComparison::Unstaged {
        // The private index copy below is rewritten whole, never as a split
        // index whose shared files would be written into the repository.
        // safecrlf only adds per-file EOL warnings; the diff is unchanged.
        args.extend(
            ["-c", "core.splitIndex=false", "-c", "core.safecrlf=false"].map(str::to_string),
        );
        disabled_filter_config(root, control)?
    } else {
        Vec::new()
    };
    args.extend(
        [
            "diff",
            "--raw",
            "--numstat",
            "--patch",
            "-z",
            "--full-index",
            "--abbrev=64",
            "--no-ext-diff",
            "--no-textconv",
            "--no-color",
            "--no-relative",
            "--no-exit-code",
            "--no-quiet",
            "--find-renames=50%",
            "-l1000",
            "--diff-algorithm=myers",
            "--no-indent-heuristic",
            "--inter-hunk-context=0",
            "--src-prefix=a/",
            "--dst-prefix=b/",
            "--output-indicator-new=+",
            "--output-indicator-old=-",
            "--output-indicator-context= ",
        ]
        .map(str::to_string),
    );
    args.push(format!(
        "--unified={}",
        source_ranges
            .as_ref()
            .map_or(3, |source| source.context_lines)
    ));
    // Dirty-submodule checks run status inside each submodule, where its own
    // clean filters would execute; unstaged reads compare submodule commits only.
    args.push(
        if comparison == DiffComparison::Unstaged {
            "--ignore-submodules=dirty"
        } else {
            "--ignore-submodules=none"
        }
        .into(),
    );
    args.push("--submodule=short".into());
    match comparison {
        DiffComparison::Staged => {
            args.push("--cached".into());
            // Unborn HEAD uses Git's native --cached empty-tree behavior.
            if let Some(oid) = &from.commit_oid {
                args.push(oid.clone());
            }
        }
        DiffComparison::Unstaged => {}
        DiffComparison::Revisions => {
            args.push(from.commit_oid.clone().ok_or("missing base identity")?);
            args.push(to.commit_oid.clone().ok_or("missing head identity")?);
        }
    }
    args.push("--".into());
    args.extend(paths.iter().cloned());
    // Porcelain diff writes refreshed stat data back to the index it read,
    // even with GIT_OPTIONAL_LOCKS=0, so unstaged reads use a private copy.
    let private_index = if comparison == DiffComparison::Unstaged {
        Some(private_index_copy(root, control)?)
    } else {
        None
    };
    let output = read_git_command_with(
        root,
        &args.iter().map(String::as_str).collect::<Vec<_>>(),
        private_index.as_ref().map(|(_, index)| index.as_path()),
        &filters,
        CAPTURE_LIMIT,
        control,
    )?;
    if !output.status.success() {
        return Err(format!(
            "Git diff failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    let (mut files, patch) = parse_diff(&output.stdout)?;
    // Bind coordinates to the complete captured diff, not a truncated patch,
    // mutable ref name, file length or mtime. A later guarded call must use the
    // same context/path selection. Source text is projected from this very
    // capture, so no second worktree read can attach stale hunk coordinates.
    let mut identity = Sha256::new();
    for part in [
        root.to_string_lossy().as_bytes(),
        from.commit_oid.as_deref().unwrap_or("").as_bytes(),
        to.commit_oid.as_deref().unwrap_or("").as_bytes(),
        &output.stdout,
    ] {
        identity.update((part.len() as u64).to_le_bytes());
        identity.update(part);
    }
    let diff_sha256 = identity
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    if source_ranges
        .as_ref()
        .and_then(|source| source.if_diff_sha256.as_ref())
        .is_some_and(|expected| !expected.eq_ignore_ascii_case(&diff_sha256))
    {
        return Err("stale_diff_coordinates: captured diff identity no longer matches; obtain new hunks before retrieving source".into());
    }
    let source_ranges = source_ranges
        .as_ref()
        .map(|source| crate::diff_source::resolve(&files, patch, source, max_files))
        .transpose()?;
    let unmatched_paths = unmatched_paths(root, comparison, [&from, &to], &paths, &files, control)?;
    let total_files = files.len();
    let additions = files.iter().filter_map(|file| file.additions).sum();
    let deletions = files.iter().filter_map(|file| file.deletions).sum();
    let binary_files = files.iter().filter(|file| file.binary).count();
    files.truncate(max_files);
    let mut returned_patch_bytes = patch.len().min(max_patch_bytes);
    let (patch_text, patch_encoding) = match std::str::from_utf8(patch) {
        Ok(text) => {
            while !text.is_char_boundary(returned_patch_bytes) {
                returned_patch_bytes -= 1;
            }
            (text[..returned_patch_bytes].to_string(), "utf8")
        }
        Err(_) => {
            use std::fmt::Write;
            // Two hex digits per byte: max_patch_bytes bounds the returned text.
            returned_patch_bytes = patch.len().min(max_patch_bytes / 2);
            let mut hex = String::with_capacity(returned_patch_bytes * 2);
            for byte in &patch[..returned_patch_bytes] {
                let _ = write!(hex, "{byte:02x}");
            }
            (hex, "hex")
        }
    };
    Ok(DiffInspection {
        repository_root: root.to_path_buf(),
        comparison,
        from,
        to,
        paths,
        unmatched_paths,
        git_args: args,
        filter_policy: "external_diff_and_textconv_disabled; configured_clean_and_process_filters_disabled; git_builtin_normalization",
        untracked_included: false,
        coherent_snapshot_verified: comparison == DiffComparison::Revisions,
        total_files,
        files,
        files_truncated: total_files > max_files,
        additions,
        deletions,
        binary_files,
        patch: patch_text,
        patch_encoding,
        total_patch_bytes: patch.len(),
        returned_patch_bytes,
        patch_truncated: returned_patch_bytes < patch.len(),
        warnings: bounded_warnings(&output.stderr),
        diff_sha256,
        source_ranges,
    })
}

/// Git's stderr, bounded so default limits still fit direct delivery. Both
/// ends are kept: Git prints rename-limit diagnostics last.
pub(crate) fn bounded_warnings(stderr: &[u8]) -> String {
    let text = String::from_utf8_lossy(stderr);
    if text.len() <= MAX_WARNING_BYTES {
        return text.into_owned();
    }
    let mut head = MAX_WARNING_BYTES / 2;
    while !text.is_char_boundary(head) {
        head -= 1;
    }
    let mut tail = text.len() - MAX_WARNING_BYTES / 2;
    while !text.is_char_boundary(tail) {
        tail += 1;
    }
    let omitted = tail - head;
    format!(
        "{}\n[{omitted} bytes of Git warnings omitted]\n{}",
        &text[..head],
        &text[tail..]
    )
}

/// A private copy of the live index (absent before the first add); Git may
/// rewrite the copy, never the live index or its lock.
pub(crate) fn private_index_copy(
    root: &Path,
    control: &GitCommandControl,
) -> Result<(tempfile::TempDir, PathBuf), String> {
    let live = read_git(
        root,
        &["rev-parse", "--git-path", "index"],
        32 * 1024,
        control,
    )?;
    let live = root.join(live.trim_end_matches(['\r', '\n']));
    let directory = tempfile::tempdir().map_err(|error| error.to_string())?;
    let copy = directory.path().join("index");
    // std opens files share-delete, so Git's lock-and-rename updates proceed.
    match std::fs::File::open(live) {
        Ok(mut source) => {
            let mut target = std::fs::File::create(&copy).map_err(|error| error.to_string())?;
            std::io::copy(&mut source, &mut target).map_err(|error| error.to_string())?;
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(format!("cannot copy the Git index: {error}")),
    }
    Ok((directory, copy))
}

fn covers(path: &str, name: &str) -> bool {
    name.strip_prefix(path)
        .is_some_and(|rest| rest.is_empty() || rest.starts_with('/'))
}

/// Literal paths without diff records are checked against the endpoints, so a
/// path matching nothing (e.g. wrong case) is reported, not read as unchanged.
fn unmatched_paths(
    root: &Path,
    comparison: DiffComparison,
    endpoints: [&DiffEndpoint; 2],
    paths: &[String],
    files: &[DiffFile],
    control: &GitCommandControl,
) -> Result<Vec<String>, String> {
    let mut unmatched = paths
        .iter()
        .filter(|path| {
            !files
                .iter()
                .any(|file| covers(path, &file.old_path) || covers(path, &file.new_path))
        })
        .cloned()
        .collect::<Vec<_>>();
    // Staged index entries absent from HEAD are additions the diff lists. The
    // unstaged endpoints are the index and working tree, so only the index
    // listing below decides; HEAD may hold a path removed from the index.
    let trees = match comparison {
        DiffComparison::Unstaged => Vec::new(),
        DiffComparison::Staged | DiffComparison::Revisions => endpoints
            .iter()
            .filter(|endpoint| endpoint.kind == "commit_tree")
            .filter_map(|endpoint| endpoint.tree_oid.clone())
            .collect(),
    };
    for tree in &trees {
        if unmatched.is_empty() {
            break;
        }
        let mut args = vec![
            "--literal-pathspecs",
            "ls-tree",
            "-z",
            "--name-only",
            tree.as_str(),
            "--",
        ];
        args.extend(unmatched.iter().map(String::as_str));
        let output = read_git_command(root, &args, CAPTURE_LIMIT, control)?;
        if !output.status.success() {
            return Err(format!(
                "Git path check failed: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            ));
        }
        let names = String::from_utf8_lossy(&output.stdout);
        unmatched.retain(|path| !names.split_terminator('\0').any(|name| covers(path, name)));
    }
    if comparison == DiffComparison::Unstaged && !unmatched.is_empty() {
        let mut args = vec!["--literal-pathspecs", "ls-files", "-z", "--cached", "--"];
        args.extend(unmatched.iter().map(String::as_str));
        let names = read_git_lossy(root, &args, CAPTURE_LIMIT, control)?;
        unmatched.retain(|path| !names.split_terminator('\0').any(|name| covers(path, name)));
    }
    Ok(unmatched)
}

/// Git emits raw records, then NUL-delimited numstat, then NUL + exact patch.
/// Parse only metadata; never regenerate, normalize or infer patch hunks.
fn parse_diff(bytes: &[u8]) -> Result<(Vec<DiffFile>, &[u8]), String> {
    if bytes.is_empty() {
        return Ok((Vec::new(), bytes));
    }
    let boundary = bytes
        .windows(2)
        .position(|pair| pair == b"\0\0")
        .ok_or("missing Git patch separator")?;
    let metadata =
        std::str::from_utf8(&bytes[..boundary]).map_err(|_| "Git paths require UTF-8")?;
    let mut fields = metadata.split('\0').peekable();
    let mut files = Vec::new();
    while fields.peek().is_some_and(|field| field.starts_with(':')) {
        let raw = fields.next().ok_or("missing Git raw header")?;
        let header = raw[1..].split(' ').collect::<Vec<_>>();
        if header.len() != 5 || !valid_oid(header[2]) || !valid_oid(header[3]) {
            return Err(
                "unsupported Git raw header (unmerged combined diffs are not supported)".into(),
            );
        }
        let old_path = fields.next().ok_or("missing Git raw path")?.to_string();
        let renamed = header[4].starts_with(['R', 'C']);
        let new_path = if renamed {
            fields
                .next()
                .ok_or("missing Git rename destination")?
                .to_string()
        } else {
            old_path.clone()
        };
        files.push(DiffFile {
            status: header[4].into(),
            old_path,
            new_path,
            old_mode: header[0].into(),
            new_mode: header[1].into(),
            old_oid: header[2].into(),
            new_oid: header[3].into(),
            similarity_percent: if renamed {
                Some(
                    header[4][1..]
                        .parse()
                        .map_err(|_| "invalid Git similarity")?,
                )
            } else {
                None
            },
            binary: false,
            additions: None,
            deletions: None,
        });
    }
    for file in &mut files {
        let stat = fields.next().ok_or("missing Git numstat")?;
        let mut stat = stat.splitn(3, '\t');
        let added = stat.next().ok_or("missing additions")?;
        let deleted = stat.next().ok_or("missing deletions")?;
        let name = stat.next().ok_or("missing numstat path")?;
        let (old, new) = if name.is_empty() {
            (
                fields.next().ok_or("missing numstat source")?,
                fields.next().ok_or("missing numstat destination")?,
            )
        } else {
            (name, name)
        };
        if old != file.old_path || new != file.new_path {
            return Err("Git raw/numstat identity mismatch".into());
        }
        file.binary = added == "-" && deleted == "-";
        if !file.binary {
            file.additions = Some(added.parse().map_err(|_| "invalid additions")?);
            file.deletions = Some(deleted.parse().map_err(|_| "invalid deletions")?);
        }
    }
    if fields.next().is_some() {
        return Err("unexpected Git metadata records".into());
    }
    Ok((files, &bytes[boundary + 2..]))
}

#[derive(Clone, Copy, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum RangeTraversal {
    AllParents,
    FirstParent,
}

#[derive(Serialize)]
pub struct RangeCommit {
    pub commit_oid: String,
    pub parent_oids: Vec<String>,
    pub is_merge: bool,
    pub subject: String,
}

#[derive(Serialize)]
pub struct CommitRangeSummary {
    pub endpoint_diff: DiffInspection,
    pub traversal: RangeTraversal,
    pub selection: &'static str,
    pub merge_handling: &'static str,
    pub merge_bases: Vec<String>,
    pub base_is_ancestor: Option<bool>,
    pub head_is_ancestor: Option<bool>,
    pub history_complete: bool,
    pub total_commits: usize,
    pub commits: Vec<RangeCommit>,
    pub commits_truncated: bool,
    pub statistics_scope: &'static str,
}

pub async fn summarize_commit_range(
    cwd: PathBuf,
    request: DiffRequest,
    traversal: RangeTraversal,
    max_commits: usize,
) -> Result<CommitRangeSummary, String> {
    if request.comparison != DiffComparison::Revisions
        || !(1..=MAX_INSPECTION_ENTRIES).contains(&max_commits)
    {
        return Err("range summary requires two revisions and 1..1000 commits".into());
    }
    let control = GitCommandControl::new();
    let _cancellation = ReadCancellation(control.clone());
    tokio::task::spawn_blocking(move || {
        let root = repository_root(&cwd, &control)?;
        let endpoint_diff = capture_diff(&root, request, &control)?;
        let base = endpoint_diff.from.commit_oid.as_deref().ok_or("missing base")?;
        let head = endpoint_diff.to.commit_oid.as_deref().ok_or("missing head")?;
        let history_complete = read_git(&root, &["rev-parse", "--is-shallow-repository"], 1024, &control)?.trim() == "false";
        let merge = read_git_command(&root, &["merge-base", "--all", base, head], 128 * 1024, &control)?;
        if !merge.status.success() && merge.status.code() != Some(1) {
            return Err(format!("Git ancestry unavailable: {}", String::from_utf8_lossy(&merge.stderr).trim()));
        }
        let merge_bases = String::from_utf8(merge.stdout).map_err(|_| "invalid merge bases")?
            .split_whitespace().map(str::to_string).collect::<Vec<_>>();
        if merge_bases.iter().any(|oid| !valid_oid(oid)) { return Err("invalid merge-base identity".into()); }
        let ancestry = |oid: &str| if merge_bases.iter().any(|base| base == oid) { Some(true) } else if history_complete { Some(false) } else { None };
        let base_is_ancestor = ancestry(base);
        let head_is_ancestor = ancestry(head);
        let excluded = format!("^{base}");
        let mut walk = vec![head, &excluded];
        if matches!(traversal, RangeTraversal::FirstParent) { walk.push("--first-parent"); }
        let mut count_args = vec!["rev-list", "--count"];
        count_args.extend(walk.iter().copied());
        count_args.push("--");
        let total_commits = read_git(&root, &count_args, 1024, &control)?.trim().parse::<usize>().map_err(|_| "invalid commit count")?;
        let limit = format!("--max-count={max_commits}");
        let mut log_args = vec!["log", "-z", "--format=%H%x00%P%x00%s", "--topo-order", "--no-decorate", "--no-patch", "--no-show-signature", "--encoding=UTF-8", &limit];
        log_args.extend(walk);
        log_args.push("--");
        // Subjects without an encoding header may hold legacy bytes; decode
        // them lossily rather than fail the summary. IDs stay ASCII.
        let log = read_git_lossy(&root, &log_args, 2 * 1024 * 1024, &control)?;
        let fields = log.split_terminator('\0').collect::<Vec<_>>();
        if fields.len() % 3 != 0 { return Err("invalid Git commit records".into()); }
        let mut commits = Vec::new();
        for &[commit_oid, parents, subject] in fields.as_chunks::<3>().0 {
            let mut parent_oids = parents.split_whitespace().map(str::to_string).collect::<Vec<_>>();
            if !history_complete && parent_oids.is_empty() {
                // Pretty-log parents follow shallow grafts, not the raw commit.
                // A boundary merge must not become a purported root/non-merge.
                let raw = read_git_lossy(&root, &["cat-file", "commit", commit_oid], 1024 * 1024, &control)?;
                parent_oids = raw.split_once("\n\n").ok_or("invalid raw commit header")?.0
                    .lines().filter_map(|line| line.strip_prefix("parent ").map(str::to_string)).collect();
            }
            if !valid_oid(commit_oid) || parent_oids.iter().any(|oid| !valid_oid(oid)) { return Err("invalid commit identity".into()); }
            commits.push(RangeCommit { commit_oid: commit_oid.into(), is_merge: parent_oids.len() > 1, parent_oids, subject: subject.into() });
        }
        if commits.len() != total_commits.min(max_commits) { return Err("Git commit count/list mismatch".into()); }
        Ok(CommitRangeSummary { endpoint_diff, traversal,
            selection: "base..head: reachable from head, excluding commits reachable from base; no path filtering",
            merge_handling: match traversal { RangeTraversal::AllParents => "follow all parents; include each merge once", RangeTraversal::FirstParent => "follow only first parents at merges; include merge commits once" },
            merge_bases, base_is_ancestor, head_is_ancestor, history_complete,
            total_commits, commits_truncated: total_commits > commits.len(), commits,
            statistics_scope: "endpoint trees only; never a sum of per-commit statistics; paths restrict only endpoint_diff",
        })
    }).await.map_err(|error| error.to_string())?
}
